# Scree plot and cumulative proportion of variance for data generated by two latent factors.
set.seed(0)
n <- 200
p <- 8
f <- matrix(rnorm(n * 2), n, 2)
L <- matrix(c(0.9, 0.0, 0.8, 0.2, 0.85, 0.1, 0.7, 0.3,
              0.1, 0.9, 0.2, 0.8, 0.0, 0.85, 0.3, 0.6), ncol = 2, byrow = TRUE)
x <- f %*% t(L) + 0.45 * matrix(rnorm(n * p), n, p)

pc <- prcomp(x, scale. = TRUE)  # PCA of the correlation matrix R
lam <- pc$sdev^2                # eigenvalues of R
print(summary(pc))

par(mfrow = c(1, 2))
plot(1:p, lam, type = "b", pch = 19, col = "steelblue",
     xlab = "component i", ylab = "eigenvalue of R", main = "scree plot")
abline(h = 1, lty = 2, col = "firebrick")
legend("topright", bty = "n", legend = "eigenvalue 1 (Kaiser)", lty = 2, col = "firebrick")

barplot(cumsum(lam) / p, names.arg = 1:p, col = adjustcolor("steelblue", 0.7), ylim = c(0, 1.05),
        xlab = "number of components k", ylab = "cumulative proportion",
        main = "cumulative proportion of variance")
abline(h = 0.8, lty = 2, col = "firebrick")
